mapper.select:
SELECT TS.SERVICE_ID, TS.WORK_CD, TS.CAR_NO, TS.COMPANY_ID, TC.COMPANY_NM, TM.MORT_NM, TM.PAY_NM, DECODE(TS.GOVT_ID, 'HAMYA', '함양', 'CHANG', '창원', 'HAMAN', '함안', 'DAEGU', '대구') AS GOVT_ID2, TS.MEMBER_ID, TMD.MEMBER_NM, TO_CHAR(TS.REQUEST_DT, 'YYYYMMDD') AS REQUEST_DT,
TO_CHAR(TS.REQUEST_DT, 'MM-DD HH24:MI') AS REQUEST_DT2,
TO_CHAR( DECODE(TM.PAY_GB, 'A', TS.REQUEST_DT, 'B', DECODE(TS.PROC_ST, 'REQ', TS.REQUEST_DT, 'S_REQ', TM.PAY_DT)), 'MM-DD HH24:MI') AS REQUEST_DT2,
TS.REQUEST_DT AS REQUEST_DT3, TO_CHAR(TS.PROC_DT, 'YYYYMMDD') AS PROC_DT, TS.PROC_ST, TS.EMER_YN, TM.PAY_ST, TM.BOND_AMT, TM.TOTAL_AMT, TM.VBANK_NO, TM.DSIGN_GB, TM.DSIGN_ST, TS.JUDGE_ST, TM.IDEN_ST, TM.IDEN_DT, TO_CHAR(TS.JUDGE_DT, 'YYYYMMDD') AS JUDGE_DT, TM.PAY_TP, TS.AUTO_YN, TS.GOVT_ID, TS.IMPO_YN, TC.COMPANY_NO, (SELECT MAX(TCI.CARID_NO) FROM TR_CARINFO TCI WHERE TCI.SERVICE_ID = TS.SERVICE_ID) AS CARID_NO, (SELECT MAX(TCI.EULBU_NO) FROM TR_CARINFO TCI WHERE TCI.SERVICE_ID = TS.SERVICE_ID) AS EULBU_NO, (SELECT TO_CHAR(MAX(TCI.MORTREG_DT), 'YYYYMMDD') FROM TR_CARINFO TCI WHERE TCI.SERVICE_ID = TS.SERVICE_ID) AS MORTREG_DT FROM TR_MORTGAGE TM, TR_SERVICE TS, TM_COMPANY TC, TM_MEMBER_DT TMD WHERE TM.SERVICE_ID = TS.SERVICE_ID AND TS.COMPANY_ID = TC.COMPANY_ID AND TS.MEMBER_ID = TMD.MEMBER_ID AND TC.COMPANY_ID = TMD.COMPANY_ID AND TS.REQUEST_DT BETWEEN TO_DATE(#{START_DT} || '00:00:00', 'YYYYMMDDHH24:MI:SS') AND TO_DATE(#{END_DT} || '23:59:59', 'YYYYMMDDHH24:MI:SS') AND TS.WORK_CD = #{WORK_CD}
AND TS.COMPANY_ID = #{COMPANY_ID}
AND TS.BRANCH_ID = #{BRANCH_ID}
AND TS.SANGSA_ID = #{SANGSA_ID}
AND TS.PROC_ST = #{PROC_ST}
AND TS.PROC_ST <> 'DEL'
AND TS.PROC_ST <> 'C_SAV'
AND TS.JUDGE_ST IS NOT NULL
AND TS.JUDGE_ST = #{JUDGE_ST}
AND TS.CAR_NO LIKE '%' || #{CAR_NO} || '%'
AND TMD.MEMBER_NM LIKE '%' || #{USER_NM} || '%'
AND TM.PAY_NM LIKE '%' || #{PAY_NM} || '%'
AND TM.MORT_NM LIKE '%' || #{MORT_NM} || '%'
AND TM.PAY_ST = #{PAY_ST}
AND TS.GOVT_ID = #{GOVT_ID}
AND TS.AUTO_YN = #{AUTO_YN}
AND MOD(SUBSTR(TS.SERVICE_ID, -1), 2) = 0
AND MOD(SUBSTR(TS.SERVICE_ID, -1), 2) = 1
AND TS.READ_YN IS NULL
AND TS.IMPO_YN = #{IMPO_YN}
ORDER BY TS.REQUEST_DT DESC
ORDER BY TS.EMER_YN ASC, REQUEST_DT2 ASC
ORDER BY TS.EMER_YN ASC, TS.REQUEST_DT DESC

SELECT COMPANY_ID, BIZ_NO, COMPANY_NO, COMPANY_NM
FROM TM_COMPANY
WHERE USE_YN = 'Y'
  AND ASSOCIATION_ID = #{associationId}
  AND COMPANY_ID = #{companyId}
UNION ALL
SELECT COMPANY_ID, BIZ_NO, COMPANY_NO, COMPANY_NM
FROM TM_COMPANY_HIS
WHERE COMPANY_ID = #{companyId}

