CAR_NO = #{CAR_NO}, PROC_ST = #{PROC_ST}, JUDGE_ST = #{JUDGE_ST}, RETURN_TX = #{RETURN_TX}, UPD_USER = #{MEMBER_ID}, UPD_DATE = SYSDATE
WHERE SERVICE_ID = #{SERVICE_ID}

